// App.jsx (reference repo version, Vite project: App.jsx in src/, children in src/components/)
import Header from "./components/Header";
import Footer from "./components/Footer";
import Note from "./components/Note";

function App() {
  return (
    <>
      <Header />
      <Note />
      <Footer />
    </>
  );
}
export default App;

// components/Header.jsx
function Header() {
  return (
    <header>
      <h1>Keeper App</h1>
    </header>
  );
}
export default Header;

// components/Footer.jsx
const year = new Date().getFullYear(); // computed once when the module loads

function Footer() {
  return (
    <footer>
      <p>Copyright © {year}. All rights reserved.</p>
    </footer>
  );
}
export default Footer;

// components/Note.jsx
function Note() {
  return (
    <div className="note">
      <h1>This is the note title</h1>
      <p>This is the note content</p>
    </div>
  );
}
export default Note;
